SELECT json_build_object(
 'tables',(SELECT coalesce(json_agg(json_build_object('name',c.relname,'kind',c.relkind,'persistence',c.relpersistence,'rowSecurity',c.relrowsecurity,'forcedRowSecurity',c.relforcerowsecurity,'ownerMatches',pg_get_userbyid(c.relowner)=CURRENT_USER) ORDER BY c.relname),'[]'::json) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('TechnicalDocumentAcquisition')),
 'columns',(SELECT coalesce(json_agg(json_build_object('table',table_name,'name',column_name,'type',data_type,'udt',udt_name,'nullable',is_nullable,'default',column_default) ORDER BY table_name,ordinal_position),'[]'::json) FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('TechnicalDocumentAcquisition')),
 'triggers',(SELECT coalesce(json_agg(json_build_object('table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'deferrable',t.tgdeferrable,'initiallyDeferred',t.tginitdeferred,'functionSchema',pn.nspname,'functionName',p.proname,'definition',pg_get_triggerdef(t.oid)) ORDER BY t.tgname),'[]'::json) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_proc p ON p.oid=t.tgfoid JOIN pg_namespace pn ON pn.oid=p.pronamespace WHERE n.nspname='public' AND NOT t.tgisinternal AND t.tgname IN ('technical_acquisition_immutable','technical_acquisition_no_truncate','technical_acquisition_atomic','technical_canonical_document_immutable','technical_canonical_version_immutable','technical_acquisition_document_atomic','technical_acquisition_version_atomic')),
 'functions',(SELECT coalesce(json_agg(json_build_object('name',p.proname,'schema',n.nspname,'arguments',pg_get_function_identity_arguments(p.oid),'returns',pg_get_function_result(p.oid),'language',l.lanname,'volatility',p.provolatile,'securityDefiner',p.prosecdef,'configuration',p.proconfig,'ownerMatches',pg_get_userbyid(p.proowner)=CURRENT_USER,'bodySha256',encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')) ORDER BY p.proname),'[]'::json) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE n.nspname='public' AND p.proname IN ('fai_technical_acquisition_atomic','fai_technical_canonical_atomic','fai_technical_canonical_immutable')),
 'constraints',(SELECT coalesce(json_agg(json_build_object('table',c.conrelid::regclass::text,'name',c.conname,'definition',pg_get_constraintdef(c.oid),'validated',c.convalidated,'type',c.contype) ORDER BY c.conname),'[]'::json) FROM pg_constraint c JOIN pg_class t ON t.oid=c.conrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='public' AND t.relname IN ('TechnicalDocumentAcquisition')),
 'indexes',(SELECT coalesce(json_agg(json_build_object('table',tablename,'name',indexname,'definition',indexdef) ORDER BY indexname),'[]'::json) FROM pg_indexes WHERE schemaname='public' AND tablename IN ('TechnicalDocumentAcquisition'))
);
